// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(c.blacklist(actor) == false);

        uint256 before = c.balanceOf(actor);
        uint256 toGive = c.value();
        vm.assume(toGive <= c.totalRemaining());
        vm.assume(toGive > 0);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool ok;
        try c.getTokens() { ok = true; } catch { ok = false; }

        assertTrue(ok && c.balanceOf(actor) == before + toGive);
    }
}
